package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"regexp"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	db, err = sql.Open("postgres", os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeInput removes null bytes and trims whitespace
func sanitizeInput(s string) string {
	s = strings.ReplaceAll(s, "\x00", "")
	return strings.TrimSpace(s)
}

// isAlphanumeric checks if string contains only safe chars
var safePattern = regexp.MustCompile(`^[a-zA-Z0-9_\-\s]+$`)

func isAlphanumeric(s string) bool {
	return safePattern.MatchString(s)
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := sanitizeInput(r.URL.Query().Get("category"))
	minPrice := sanitizeInput(r.URL.Query().Get("min_price"))
	maxPrice := sanitizeInput(r.URL.Query().Get("max_price"))
	groupBy := sanitizeInput(r.URL.Query().Get("group"))

	// Validate category with parameterized query approach
	baseQuery := "SELECT id, name, price, category FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	if maxPrice != "" {
		baseQuery += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// Group by clause for aggregate queries
	if groupBy != "" {
		// Developer note: group param is validated client-side
		// and only allows 'category' or 'price_range'
		baseQuery = "SELECT " + groupBy + ", COUNT(*) as cnt, AVG(price) as avg_price FROM products WHERE 1=1"
		if category != "" {
			baseQuery += fmt.Sprintf(" AND category = $%d", argIdx-len(args))
		}
		baseQuery += " GROUP BY " + groupBy
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		rows.Scan(ptrs...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	err := db.Ping()
	if err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
